from typing import List


def count_levels(employeePairs: List[List[str]], employee1: str, employee2: str) -> int:
    manager = {}
    for emp, boss in employeePairs:
        manager[emp] = boss  # last entry wins

    def depth(name: str) -> int:
        d = 0
        while name in manager:
            name = manager[name]
            d += 1
        return d

    return abs(depth(employee1) - depth(employee2))

import java.util.*;

class Solution {
    int countLevels(String[][] employeePairs, String e1, String e2) {
        Map<String, String> manager = new HashMap<>();
        for (String[] p : employeePairs) manager.put(p[0], p[1]); // last entry wins
        return Math.abs(depth(e1, manager) - depth(e2, manager));
    }

    private int depth(String name, Map<String, String> manager) {
        int d = 0;
        while (manager.containsKey(name)) {
            name = manager.get(name);
            d++;
        }
        return d;
    }
}

class Solution {
public:
    int countLevels(vector<vector<string>>& employeePairs, string e1, string e2) {
        unordered_map<string, string> manager;
        for (auto& p : employeePairs) manager[p[0]] = p[1]; // last entry wins
        auto depth = [&](string name) {
            int d = 0;
            for (auto it = manager.find(name); it != manager.end(); it = manager.find(name)) {
                name = it->second;
                ++d;
            }
            return d;
        };
        return abs(depth(e1) - depth(e2));
    }
};
